import numpy as np


def cdf_from_cf(cf, x, U=200, n=200001):
    u = np.linspace(1e-10, U, n)
    g = (np.exp(-1j * u * x) * cf(u)).imag / u
    return 0.5 - np.trapezoid(g, u) / np.pi


def empirical_cf(sample, u):
    return np.mean(np.exp(1j * u * np.asarray(sample)))
